//! The MD Kanban card format.
//!
//! A card is a markdown file with YAML frontmatter. The format is a contract with
//! AI agents and with the Electron app, so reading and writing here are ports of
//! the Electron app's `parseTaskFile` and `stringifyTaskFile` (md-kanban `edebd29`),
//! checked against fixtures generated by that code. Two deliberate differences:
//! unknown frontmatter keys are kept on write, and CRLF files are understood.

mod card;
mod text;

pub use card::{CardPatch, ParsedCard, RawKey, apply_patch, now_iso, parse, set_title, write};
pub use text::{
    Date, QuickAdd, Subtask, Template, Tone, code_spans, excerpt, format_due, new_file_name,
    parse_quick_add, slugify, strip_comments, subtasks, template, toggle_subtask,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Status {
    Backlog,
    Todo,
    InProgress,
    Review,
    Done,
}

impl Status {
    pub const ALL: [Status; 5] = [
        Status::Backlog,
        Status::Todo,
        Status::InProgress,
        Status::Review,
        Status::Done,
    ];

    /// The value written in frontmatter.
    pub fn as_str(self) -> &'static str {
        match self {
            Status::Backlog => "backlog",
            Status::Todo => "todo",
            Status::InProgress => "in-progress",
            Status::Review => "review",
            Status::Done => "done",
        }
    }

    /// The column name shown on the board.
    pub fn name(self) -> &'static str {
        match self {
            Status::Backlog => "Backlog",
            Status::Todo => "To Do",
            Status::InProgress => "In Progress",
            Status::Review => "Review",
            Status::Done => "Done",
        }
    }

    /// The column colour, as 0xRRGGBB.
    pub fn color(self) -> u32 {
        match self {
            Status::Backlog => 0x6b7280,
            Status::Todo => 0x3b82f6,
            Status::InProgress => 0xf59e0b,
            Status::Review => 0x8b5cf6,
            Status::Done => 0x22c55e,
        }
    }

    pub fn parse(s: &str) -> Option<Status> {
        Status::ALL.into_iter().find(|status| status.as_str() == s)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Priority {
    Critical,
    High,
    Medium,
    Low,
}

impl Priority {
    pub const ALL: [Priority; 4] = [
        Priority::Critical,
        Priority::High,
        Priority::Medium,
        Priority::Low,
    ];

    pub fn as_str(self) -> &'static str {
        match self {
            Priority::Critical => "critical",
            Priority::High => "high",
            Priority::Medium => "medium",
            Priority::Low => "low",
        }
    }

    pub fn parse(s: &str) -> Option<Priority> {
        Priority::ALL.into_iter().find(|p| p.as_str() == s)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LineEnding {
    Lf,
    CrLf,
}

#[derive(Debug, PartialEq, Eq)]
pub enum FormatError {
    /// The frontmatter is not valid YAML, so the file must not be rewritten from parsed fields.
    BrokenFrontmatter(String),
}

impl std::fmt::Display for FormatError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FormatError::BrokenFrontmatter(e) => write!(f, "Fix the frontmatter first ({e})"),
        }
    }
}

impl std::error::Error for FormatError {}
